  if (n === 1) {
    return 1;
  }
  const decidingSeats = 2;
  const goodSeats = 1;
  return goodSeats / decidingSeats;
}

brute:
function nthPersonGetsNthSeat(n) {
  // chance[m]: probability the last passenger gets their seat when m seats remain and the
  // current random chooser's "own" seat is seat 1. Passenger 1 picks seat 1 (success), seat
  // m (failure) or a seat k in between, which hands the problem to passenger k with m - k + 1 seats.
  const chance = [0, 1];
  let sum = 0; // chance[2] + ... + chance[m - 1]
  for (let m = 2; m <= n; m++) {
    chance[m] = (1 + sum) / m;
    sum += chance[m];
  }
  return chance[n];
}

